import { lstat, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { prerelease, valid } from 'semver';

const RECORD = '.aionui-install.json';
const ID_PATTERN = /^(\d+\.\d+\.\d+)-[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/;
export type InstallRecord = { id: string; version: string; installedAt: string };

/** Accepts only installation IDs generated by this updater, never filesystem paths. */
export function isInstallId(id: string): boolean {
  const version = id.match(ID_PATTERN)?.[1];
  return !!version && valid(version) === version && !prerelease(version);
}

/** Rejects symlink directories, including the root of a recursive cleanup. */
export async function isPlainDirectory(directory: string): Promise<boolean> {
  const info = await lstat(directory);
  return info.isDirectory() && !info.isSymbolicLink();
}

/** Records provenance only after an installation has passed validation. */
export async function writeInstallRecord(directory: string, record: InstallRecord): Promise<void> {
  await writeFile(path.join(directory, RECORD), JSON.stringify({ ...record, owner: 'aionui-codex-v1' }), {
    flag: 'wx',
    mode: 0o600,
  });
}

/** Unrecognised or modified installations are retained rather than guessed to be disposable. */
export async function readInstallRecord(directory: string, id: string): Promise<InstallRecord | null> {
  try {
    if (!isInstallId(id) || !(await isPlainDirectory(directory))) return null;
    const file = path.join(directory, RECORD);
    if (!(await lstat(file)).isFile()) return null;
    const record = JSON.parse(await readFile(file, 'utf8')) as Partial<InstallRecord> & { owner?: string };
    if (
      record.owner !== 'aionui-codex-v1' ||
      record.id !== id ||
      typeof record.version !== 'string' ||
      !id.startsWith(`${record.version}-`) ||
      typeof record.installedAt !== 'string' ||
      !Number.isFinite(Date.parse(record.installedAt))
    )
      return null;
    return { id, version: record.version, installedAt: record.installedAt };
  } catch {
    return null;
  }
}
